Object.assign(semanticVariants, variantMaterialDecisions);
for (const row of rows) {
  const archiveId = row[0].split(':').at(-1);
  if (semanticVariants[archiveId]) {
    row[2] = 'variant'; row[3] = semanticVariants[archiveId][0]; row[11] = semanticVariants[archiveId][1];
  } else if (semanticDuplicates[archiveId]) {
    row[10] = 'rejected'; row[11] = semanticDuplicates[archiveId];
  } else if (semanticKeepReasons[archiveId]) row[11] = semanticKeepReasons[archiveId];
}

// Derivations are relative to the named source root for the master archive.
// Other archives are identified by their stable archive_ref only.
for (const row of rows) {
  const sourceRoot = 'data/world-catalogs/novgorod/sources/master-archive-v1/';
  if (row[5].startsWith(sourceRoot)) row[5] = row[5].slice(sourceRoot.length);
  else row[5] = row[0].split(':').at(-1);
}

module.exports = { rows, semanticVariants, semanticDuplicates, semanticKeepReasons, craftsOwnerHandoffs, craftsBicHandoffs };
